import{_ as t,C as o,o as l,c as p,j as a,a as s,E as r,a2 as c}from"./chunks/framework.BetZR81g.js";const m=JSON.parse('{"title":"用 Qt 6 写一个 DeepSeek 桌面客户端","description":"把 API Key 和会话记录留在本地，用 Qt 6 做一个带流式输出、Markdown 渲染和主题切换的桌面聊天客户端。","frontmatter":{"title":"用 Qt 6 写一个 DeepSeek 桌面客户端","titleHtml":"用 Qt 6 写一个 DeepSeek <span class=\\"nowrap\\">桌面客户端</span>","date":"2026-10-26","category":"桌面应用","tags":["Qt","C++","桌面应用"],"description":"把 API Key 和会话记录留在本地，用 Qt 6 做一个带流式输出、Markdown 渲染和主题切换的桌面聊天客户端。","read":6,"order":1},"headers":[],"relativePath":"blog/posts/qt-deepseek-client.md","filePath":"blog/posts/qt-deepseek-client.md"}'),i={name:"blog/posts/qt-deepseek-client.md"};function d(k,e,h,b,g,u){const n=o("ArticleMeta");return l(),p("div",null,[e[0]||(e[0]=a("h1",{id:"用-qt-6-写一个-deepseek-桌面客户端",tabindex:"-1"},[s("用 Qt 6 写一个 DeepSeek "),a("span",{class:"nowrap"},"桌面客户端"),s(),a("a",{class:"header-anchor",href:"#用-qt-6-写一个-deepseek-桌面客户端","aria-label":'Permalink to "用 Qt 6 写一个 DeepSeek <span class="nowrap">桌面客户端</span>"'},"​")],-1)),r(n),e[1]||(e[1]=c(`<p>浏览器里的 AI 聊天工具已经很多，但我还是想要一个单独的桌面窗口：不用一直开着浏览器标签页，快捷键随手可用。DeepSeek API Client 就是在这个想法下写出来的，技术栈是 Qt 6 + C++。</p><h2 id="它包含哪些功能" tabindex="-1">它包含哪些功能 <a class="header-anchor" href="#它包含哪些功能" aria-label="Permalink to &quot;它包含哪些功能&quot;">​</a></h2><p>项目的功能都围绕“本地优先”展开：</p><ul><li><strong>多会话管理</strong>：新建、重命名、删除对话，历史记录自动写入 <code>sessions.json</code>。</li><li><strong>流式对话</strong>：回复边生成边显示，也可以中途停止。</li><li><strong>Markdown 渲染</strong>：代码块、表格、列表、引用都能正常显示。</li><li><strong>深色 / 浅色主题</strong>：一键切换，主题写在 QSS 文件里。</li><li><strong>参数配置</strong>：API Key、模型、温度、最大 Token、思考模式。</li><li><strong>导出对话</strong>：Markdown、HTML 或纯文本。</li><li><strong>快捷键</strong>：<code>Ctrl+Enter</code> 发送、<code>Ctrl+N</code> 新建、<code>Ctrl+D</code> 删除。</li></ul><p>这些功能都不复杂，难的是让它们在一个桌面窗口里互相不打架。</p><h2 id="界面与业务逻辑分开" tabindex="-1">界面与业务逻辑分开 <a class="header-anchor" href="#界面与业务逻辑分开" aria-label="Permalink to &quot;界面与业务逻辑分开&quot;">​</a></h2><p>桌面客户端最容易写成“按钮回调里塞满业务代码”。一旦要换主题、加导出格式或者改会话存储，就会牵一发动全身。这个项目从一开始就按模块拆分：界面负责展示和输入，会话、请求、配置各自独立。最直接的体现是主题：<code>light.txt</code>、<code>dark.txt</code> 和 <code>MarkDown.qss</code> 都是独立文件，和主程序放在同一目录，换主题不需要改 C++ 代码。</p><blockquote><p>代价是发布时必须把 QSS 文件一起打包，否则程序会找不到样式。这是一个很小但很容易踩的发布细节。</p></blockquote><h2 id="流式输出" tabindex="-1">流式输出 <a class="header-anchor" href="#流式输出" aria-label="Permalink to &quot;流式输出&quot;">​</a></h2><p>流式对话的体验取决于两件事：增量内容要立刻出现在界面上，以及用户点“停止”时能真正停下来。前者要求网络层每收到一段内容就通知界面，后者要求请求生命周期可取消，而不是等整个回复结束再丢弃。</p><p>在这类客户端里，我更愿意把“请求状态”当成一等公民：空闲、请求中、已停止、失败，界面只根据状态切换按钮和光标。这样停止、重试、切换会话都不会出现“看起来停了，其实还在请求”的尴尬。</p><h2 id="markdown-与主题" tabindex="-1">Markdown 与主题 <a class="header-anchor" href="#markdown-与主题" aria-label="Permalink to &quot;Markdown 与主题&quot;">​</a></h2><p>AI 回复里的代码和表格很多，纯文本显示会很难读。项目把 Markdown 的样式放在独立的 <code>MarkDown.qss</code> 里，配合代码高亮，让回复在深色和浅色主题下都保持一致的可读性。</p><p>配置项也由客户端自己管理：API Key、模型、温度、最大 Token 和思考模式都可以在首次启动的设置窗口里填写，之后也能从菜单里修改。整个使用过程不需要登录网页版控制台。</p><h2 id="构建与运行" tabindex="-1">构建与运行 <a class="header-anchor" href="#构建与运行" aria-label="Permalink to &quot;构建与运行&quot;">​</a></h2><p>源码需要 Qt 6.4 或更高版本、CMake 3.16+，以及支持 C++17 的编译器（MSVC 2022 或 MinGW 64-bit）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">git</span><span style="color:#9ECBFF;"> clone</span><span style="color:#9ECBFF;"> https://github.com/Stan-Vincent/DeepSeek-API-Client-QT.git</span></span>
<span class="line"><span style="color:#79B8FF;">cd</span><span style="color:#9ECBFF;"> DeepSeek-API-Client-QT</span></span>
<span class="line"><span style="color:#B392F0;">mkdir</span><span style="color:#9ECBFF;"> build</span><span style="color:#E1E4E8;"> &amp;&amp; </span><span style="color:#79B8FF;">cd</span><span style="color:#9ECBFF;"> build</span></span>
<span class="line"><span style="color:#B392F0;">cmake</span><span style="color:#9ECBFF;"> ..</span></span>
<span class="line"><span style="color:#B392F0;">cmake</span><span style="color:#79B8FF;"> --build</span><span style="color:#9ECBFF;"> .</span><span style="color:#79B8FF;"> --config</span><span style="color:#9ECBFF;"> Release</span></span></code></pre></div><p>如果直接用 Release 包，解压后要保证主程序和样式文件在同一目录：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>DeepSeek_Chat.exe</span></span>
<span class="line"><span>light.txt</span></span>
<span class="line"><span>dark.txt</span></span>
<span class="line"><span>MarkDown.qss</span></span></code></pre></div><p>缺少样式文件时界面不会按预期显示；缺少 VC++ 运行时则可能提示 <code>VCRUNTIME140.dll</code> 找不到。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这是一个功能不算庞大的客户端，但它把“本地存储、流式输出、Markdown、主题、配置、导出”这些点在 Qt 里串了一遍。对我来说，它更像是一个桌面应用结构的练习：先把边界划清楚，再往里面填功能。</p><p>源码在 <a href="https://github.com/Stan-Vincent/DeepSeek-API-Client-QT" target="_blank" rel="noreferrer">GitHub</a>，Release 页面也提供了编译好的 Windows 包。</p>`,23))])}const F=t(i,[["render",d]]);export{m as __pageData,F as default};
